async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let pending = "";
  let reachedEOF = false;
  let failed = false;

  async function visitLine(text) {
    line++;

    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      rejected++;
      return true;
    }

    accepted++;
    return (await visitor({ line, value })) !== false;
  }

  async function consume(text) {
    let start = 0;

    for (;;) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        pending += text.slice(start);
        return true;
      }

      const current = pending + text.slice(start, end);
      pending = "";
      if (!(await visitLine(current))) return false;
      start = end + 1;
    }
  }

  try {
    for (;;) {
      const { done, value } = await reader.read();
      reachedEOF = Boolean(done);

      const text = done
        ? decoder.decode()
        : decoder.decode(value, { stream: true });

      if (!(await consume(text))) {
        return { accepted, rejected, stopped: true };
      }

      if (done) {
        if (pending.length > 0 && !(await visitLine(pending))) {
          return { accepted, rejected, stopped: true };
        }
        return { accepted, rejected, stopped: false };
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    try {
      if (!reachedEOF || failed) await reader.cancel();
    } finally {
      reader.releaseLock();
    }
  }
}
